conditions.expression:
/* R46-B: agotada la espera y la mecanización de CORE sigue INCOMPLETA (ANL no ha recibido respuesta de NSE/NEW) → error de exceso de tiempo en la bandeja. Una mecanización PENDIENTE DE AUTORIZAR no es un exceso de tiempo. */
and(
  a!defaultValue(index(pv!mecNseRes, "esperar", false), false),
  a!localVariables(
    local!gestiones: a!defaultValue(index(rule!SCA2_consultaGestion(codSolicitud: pv!idSolicitud), "MSSConsultaGestion", {}), {}),
    local!mecanizaciones: if(
      a!isNullOrEmpty(local!gestiones),
      {},
      index(
        local!gestiones,
        wherecontains(
          tostring(cons!SCA2_TXT_ACCION_GESTION_MECANIZACION),
          touniformstring(a!forEach(local!gestiones, tostring(index(fv!item, "accionRealizada", ""))))
        ),
        {}
      )
    ),
    upper(tostring(if(
      a!isNullOrEmpty(local!mecanizaciones),
      "",
      index(index(local!mecanizaciones, length(local!mecanizaciones), null), "codEstGestion", "")
    ))) = cons!SCA2_TXT_EST_GESTION_INCOMPLETA
  )
)
